// use itertools::chain;


pub fn can_reach(s: String, min_jump: i32, max_jump: i32) -> bool {
    assert!(min_jump > 0);
    assert!(min_jump <= max_jump);
    assert!(min_jump >= 1);
    assert!(s.len() > 1);
    let min_jump = usize::try_from(min_jump).expect("min_jump should be positive");
    let max_jump = usize::try_from(max_jump).expect("max_jump should be positive");
    assert!(max_jump < s.len());
    let mut accessible = s.into_bytes();
    let mut obstacle_length= 0;
    for &i in accessible.iter() {
        if i == b'1' {
            obstacle_length += 1;
            if obstacle_length > max_jump {
                return false;
            } else {
                obstacle_length = 0;
            }
        }
    }
    let n = accessible.len();
    let mut reachable = vec![false; n];
    reachable[0] = true;
    if accessible[n - 1] == b'1' {
        return false;
    }
    let mut leader = 0;
    let mut tail = 0;
    for i in 0..n {
        if i > leader {
            return false;
        }
        if !reachable[i] {
            continue;
        }
        tail = tail.max(i);
        tail += reachable[tail+1..].iter().take_while(|&x| *x).count();
        let start = (i+min_jump).max(tail);
        let end = (i+max_jump).min(n-1);
        // dbg!(i, n, &start, &end);
        for j in start..=end {
            if accessible[j] == b'1' {
                continue;
            }
            accessible[j] = b'1';
            reachable[j] = true;
            // dbg!(j);
            if j == n - 1 {
                return true;
            }
            leader = leader.max(j);
            // if j + max_jump < leader {
            //     continue;
            // }
        }
    }
    false
}

#[test]
fn official1() {
    assert!(can_reach("011010".to_string(), 2, 3));
}

#[test]
fn official2() {
    assert!(!can_reach("01101110".to_string(), 2, 3));
}

#[test]
fn official7() {
    assert!(can_reach("011111000111000001011111010".to_string(), 6, 8));
}

#[test]
fn official119() {
    assert!(!can_reach("01".to_string(), 1, 1));
}

#[test]
fn official139() {
    assert!(!can_reach("0000000000".to_string(), 8, 8));
}


#[test]
#[ignore = " too long"]
fn official120() {
    let input = "";
    assert!(!can_reach(input.to_string(), 1, 49999));
}